      "path": "lib/index.js",
      "content": "/**
 * chicheng-push — host half
 *
 * A multi-channel message push plugin for the dsh web profile:
 *   - persists push channels under $DSH_HOME/push/channels.json
 *   - channel types follow the qinglong notify catalogue (Server酱, PushPlus,
 *     Bark, 钉钉机器人, 企业微信群机器人, 企业微信应用, Telegram, 飞书/Lark,
 *     ntfy, iGot, pushDeer, Gotify, 自定义 Webhook, 邮件(可选 nodemailer))
 *   - exposes a fenced JSON API at /push/api/<method> for the client half
 *   - provides the `pushNotifier` cordis service so OTHER plugins can push
 *     notifications, e.g. a cron task plugin calling
 *     `ctx.get("pushNotifier").send({ title, content })` after a run
 *
 * No third-party runtime dependencies: HTTP channels use the built-in
 * `fetch`; the email channel dynamically imports nodemailer only when
 * configured and available.
 */
import { randomUUID } from "node:crypto";
import { createHmac } from "node:crypto";
import { mkdir, readFile, writeFile, rename } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

// ---------------------------------------------------------------- identity

const name = "chicheng-push";
const NS = "chicheng-push";
const inject = ["webServer", "webRuntime"];

// ---------------------------------------------------------------- paths

const DATA_ROOT = process.env.DSH_HOME
  ? join(process.env.DSH_HOME, "push")
  : join(homedir(), ".dsh", "push");
const STORE_PATH = join(DATA_ROOT, "channels.json");

// ---------------------------------------------------------------- store

const EMPTY_STORE = { version: 1, channels: [] };
let store = structuredClone(EMPTY_STORE);
let storeDirtyTimer = null;

async function loadStore() {
  try {
    const raw = await readFile(STORE_PATH, "utf8");
    const parsed = JSON.parse(raw);
    if (parsed && Array.isArray(parsed.channels)) store = parsed;
  } catch {
    store = structuredClone(EMPTY_STORE);
  }
  if (!Array.isArray(store.channels)) store.channels = [];
}

/** Debounced atomic persist (tolerates crashes: tmp + rename). */
function scheduleSave() {
  if (storeDirtyTimer !== null) return;
  storeDirtyTimer = setTimeout(() => {
    storeDirtyTimer = null;
    void flushStore();
  }, 150);
}

async function flushStore() {
  try {
    await mkdir(DATA_ROOT, { recursive: true });
    const tmp = `${STORE_PATH}.tmp`;
    await writeFile(tmp, JSON.stringify(store, null, 2), "utf8");
    await rename(tmp, STORE_PATH);
  } catch (error) {
    console.error(`[chicheng-push] store flush failed:`, error);
  }
}

// ---------------------------------------------------------------- util

const isPlainObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);

/** Compact error text out of an unknown thrown value. */
function errorText(error) {
  if (error instanceof Error) return error.message;
  return String(error);
}

/** Base64 first line of a UTF-8 string (used by the RFC2047 title header). */
function encodeRfc2047(text) {
  return `=?UTF-8?B?${Buffer.from(String(text)).toString("base64")}?=`;
}

/** POST with the Node built-in fetch; JSON or form bodies, short timeout. */
async function httpJson(url, { method = "POST", json, form, headers = {}, raw } = {}) {
  let body;
  const finalHeaders = { ...headers };
  if (raw !== undefined) {
    body = raw;
  } else if (json !== undefined) {
    body = JSON.stringify(json);
    finalHeaders["content-type"] = "application/json";
  } else if (form !== undefined) {
    body = new URLSearchParams(form).toString();
    finalHeaders["content-type"] = "application/x-www-form-urlencoded";
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 12000);
  try {
    const res = await fetch(url, {
      method,
      headers: finalHeaders,
      body,
      signal: controller.signal,
      redirect: "follow",
    });
    const text = await res.text().catch(() => "");
    let parsed = null;
    try {
      parsed = text === "" ? null : JSON.parse(text);
    } catch {
      parsed = null;
    }
    return { status: res.status, ok: res.ok, text, json: parsed };
  } finally {
    clearTimeout(timer);
  }
}

