      { key: "emailPort", label: "端口（可选）", type: "number", placeholder: "465" },
      { key: "emailSecure", label: "是否 SSL（可选）", type: "select", options: ["true", "false"] },
      { key: "emailUser", label: "发件邮箱", type: "text", required: true },
