];

const TYPE_MAP = new Map(CHANNEL_TYPES.map((t) => [t.id, t]));

/** Lookup sender for a channel type; throws on an unknown type. */
function senderForType(typeId) {
  switch (typeId) {
    case "serverChan": return sendServerChan;
    case "pushPlus": return sendPushPlus;
    case "bark": return sendBark;
    case "dingtalkBot": return sendDingtalkBot;
    case "weWorkBot": return sendWeWorkBot;
    case "weWorkApp": return sendWeWorkApp;
    case "telegramBot": return sendTelegramBot;
    case "lark": return sendLark;
    case "ntfy": return sendNtfy;
    case "iGot": return sendIGot;
    case "pushDeer": return sendPushDeer;
    case "gotify": return sendGotify;
    case "webhook": return sendWebhook;
    case "email": return sendEmail;
    default: throw new Error(`未知渠道类型 "${typeId}"`);
  }
}

