async function sendDingtalkBot(config, title, content) {
  const token = String(config.dingtalkBotToken ?? "").trim();
  if (token === "") throw new Error("缺少钉钉机器人 Access Token");
  let url = `https://oapi.dingtalk.com/robot/send?access_token=${encodeURIComponent(token)}`;
  const secret = String(config.dingtalkBotSecret ?? "").trim();
  if (secret !== "") {
    const timestamp = Date.now();
    const hmac = createHmac("sha256", secret);
    hmac.update(`${timestamp}\n${secret}`);
    const sign = encodeURIComponent(hmac.digest("base64"));
    url += `&timestamp=${timestamp}&sign=${sign}`;
  }
  const res = await httpJson(url, { json: { msgtype: "text", text: { content: `${title}\n\n${content}` } } });
  if (res.json && res.json.errcode !== 0) {
    throw new Error(`钉钉返回 errcode=${res.json.errcode}: ${res.json.errmsg ?? res.text.slice(0, 300)}`);
  }
  if (!res.ok && !res.json) throw new Error(`钉钉 HTTP ${res.status}: ${res.text.slice(0, 300)}`);
  return `钉钉已发送 (${res.status})`;
}

