    const timestamp = Math.floor(Date.now() / 1000).toString();
    const stringToSign = `${timestamp}\n${secret}`;
    const hmac = createHmac("sha256", stringToSign);
    body.timestamp = timestamp;
    body.sign = hmac.digest("base64");
  }
  const res = await httpJson(key, { json: body });
  const code = res.json?.StatusCode ?? res.json?.code;
  if (res.json && code !== undefined && code !== 0) {
    throw new Error(`飞书返回 code=${code}: ${res.text.slice(0, 300)}`);
